begin;

delete from public.quiz_questions
where type_contenu = 'mythe'
  and slug in ('mythe-ti-kala-tikar', 'mythe-ndzana-nga-zogo-eton', 'mythe-elig-ekulu-baton-ngat-beti');


commit;

-- Contrôle : chaque mythe doit avoir exactement 5 questions.
select slug, count(*) as nb_questions
from public.quiz_questions
where type_contenu = 'mythe'
  and slug in ('mythe-ti-kala-tikar', 'mythe-ndzana-nga-zogo-eton', 'mythe-elig-ekulu-baton-ngat-beti')
group by slug
order by slug;
